diff --git a/src/storage/engine/hash_codec.cpp b/src/storage/engine/hash_codec.cpp
index f5971d6..645963d 100644
--- a/src/storage/engine/hash_codec.cpp
+++ b/src/storage/engine/hash_codec.cpp
@@ -1,16 +1,21 @@
 #include "keylane/storage/detail/hash_codec.h"

+#include <cassert>
+#include <cstring>
 #include <limits>

 namespace keylane::storage {

 namespace {

-void AppendU32(std::string* output, std::uint32_t value) {
-  output->push_back(static_cast<char>(value));
-  output->push_back(static_cast<char>(value >> 8));
-  output->push_back(static_cast<char>(value >> 16));
-  output->push_back(static_cast<char>(value >> 24));
+char* StoreU32(char* output, std::uint32_t value) {
+  // Entry headers follow arbitrary field/value bytes and need not be aligned.
+  // Byte stores preserve the durable little-endian format on every host.
+  output[0] = static_cast<char>(value);
+  output[1] = static_cast<char>(value >> 8);
+  output[2] = static_cast<char>(value >> 16);
+  output[3] = static_cast<char>(value >> 24);
+  return output + sizeof(value);
 }

 bool ReadU32(std::string_view input, std::size_t* offset,
@@ -28,9 +33,9 @@ bool ReadU32(std::string_view input, std::size_t* offset,
   return true;
 }

-void AppendU64(std::string* output, std::uint64_t value) {
-  AppendU32(output, static_cast<std::uint32_t>(value));
-  AppendU32(output, static_cast<std::uint32_t>(value >> 32));
+char* StoreU64(char* output, std::uint64_t value) {
+  output = StoreU32(output, static_cast<std::uint32_t>(value));
+  return StoreU32(output, static_cast<std::uint32_t>(value >> 32));
 }

 bool ReadU64(std::string_view input, std::size_t* offset,
@@ -153,19 +158,27 @@ absl::StatusOr<std::string> EncodeHashValue(const HashValue& value) {
     bytes = *next;
   }

-  output.reserve(bytes);
-  AppendU64(&output, kHashValueMagic);
-  AppendU32(&output, kStorageFormatVersion);
-  AppendU32(&output, kHashValueHeaderBytes);
-  AppendU32(&output, static_cast<std::uint32_t>(value.entries_.size()));
-  AppendU32(&output, 0);
-  AppendU64(&output, bytes);
-  for (const HashEntry& entry : value.entries_) {
-    AppendU32(&output, static_cast<std::uint32_t>(entry.field_.size()));
-    AppendU32(&output, static_cast<std::uint32_t>(entry.value_.size()));
-    output.append(entry.field_);
-    output.append(entry.value_);
-  }
+  // All sizes were checked before allocation. Fill the owned buffer once,
+  // avoiding per-byte capacity checks and repeated size/terminator updates.
+  // The callback cannot fail or expose partially encoded bytes to callers.
+  output.resize_and_overwrite(bytes, [&](char* destination, std::size_t) noexcept {
+    char* cursor = StoreU64(destination, kHashValueMagic);
+    cursor = StoreU32(cursor, kStorageFormatVersion);
+    cursor = StoreU32(cursor, kHashValueHeaderBytes);
+    cursor = StoreU32(cursor, static_cast<std::uint32_t>(value.entries_.size()));
+    cursor = StoreU32(cursor, 0);
+    cursor = StoreU64(cursor, bytes);
+    for (const HashEntry& entry : value.entries_) {
+      cursor = StoreU32(cursor, static_cast<std::uint32_t>(entry.field_.size()));
+      cursor = StoreU32(cursor, static_cast<std::uint32_t>(entry.value_.size()));
+      std::memcpy(cursor, entry.field_.data(), entry.field_.size());
+      cursor += entry.field_.size();
+      std::memcpy(cursor, entry.value_.data(), entry.value_.size());
+      cursor += entry.value_.size();
+    }
+    assert(cursor == destination + bytes);
+    return bytes;
+  });
   return output;
 }
